import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>

template <int BLOCK_SIZE>
__global__ void mean_reduce_dim1_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int batch,
    int dim1,
    int dim2)
{
    // one block per (b, d2) element
    int idx = blockIdx.x;
    int b = idx / dim2;
    int d2 = idx % dim2;

    // stride over dim1
    float sum = 0.0f;
    for (int i = threadIdx.x; i < dim1; i += BLOCK_SIZE) {
        int offset = ((b * dim1 + i) * dim2) + d2;
        sum += __half2float(input[offset]);
    }

    // reduction in shared memory
    __shared__ float shmem[BLOCK_SIZE];
    shmem[threadIdx.x] = sum;
    __syncthreads();

    // binary tree reduction
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shmem[threadIdx.x] += shmem[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mean = shmem[0] / static_cast<float>(dim1);
        output[b * dim2 + d2] = __float2half(mean);
    }
}

torch::Tensor mean_reduce_dim1_cuda(torch::Tensor input, int dim) {
    // only dim == 1 is supported (consistent with reference)
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::kHalf, "input must be fp16");
    TORCH_CHECK(dim == 1, "only reduction over dim=1 is implemented");

    const auto batch = input.size(0);
    const auto dim1  = input.size(1);
    const auto dim2  = input.size(2);

    auto output = torch::empty({batch, dim2}, input.options());

    const int threads = 256;
    const dim3 blocks(batch * dim2);
    const dim3 threads_per_block(threads);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "mean_reduce_dim1_cuda", ([&] {
        mean_reduce_dim1_kernel<threads>
            <<<blocks, threads_per_block, 0, at::cuda::getCurrentCUDAStream()>>>(
                input.data_ptr<__half>(),
                output.data_ptr<__half>(),
                batch,
                dim1,
                dim2);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mean_reduce_dim1_cuda", &mean_reduce_dim1_cuda, "Mean reduction over dim=1 (CUDA, fp16)");
}
"""

extension = load_inline(name="mean_reduce_ext",
                        cpp_sources="",
                        cuda_sources=src,
                        functions=["mean_reduce_dim1_cuda"],
                        verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x is expected to be fp16 CUDA tensor
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return extension.mean_reduce_dim1_cuda(x, self.dim)

# Example usage (mirrors the reference get_inputs / get_init_inputs)
if __name__ == "__main__":
    batch_size = 128
    dim1 = 4096
    dim2 = 4095

    x = torch.rand(batch_size, dim1, dim2, device='cuda', dtype=torch.float16)
    model = ModelNew(dim=1)
    y = model(x)
    print(y.shape)   # should be (128, 4095)
